import{projects,skills}from'./catalog.js';import{initGames}from'./games.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const media=matchMedia('(prefers-color-scheme:dark)');let preference;try{preference=localStorage.getItem('techbuzzs-theme')||'system'}catch{preference='system'}let theme='',previewProject=null,previewPreference='inherit',filter='all',expanded=false;const dialog=$('#previewDialog');
function applyTheme(){theme=preference==='system'?(media.matches?'dark':'light'):preference;document.documentElement.dataset.theme=theme;const button=$('#theme');button.textContent=preference==='system'?'◐':theme==='dark'?'☾':'☀';button.title='Theme: '+preference+' · click to change';button.setAttribute('aria-label','Theme: '+preference+'. Switch theme');document.querySelectorAll('[data-preview-slug]').forEach(img=>{img.src='previews/'+img.dataset.previewSlug+'-'+theme+'.png'});if(previewProject){if($('#demoFrame').hidden===false)sendTheme();const detail=$('#detailImage');if(detail)detail.src='previews/'+previewProject.slug+'-'+theme+'.png'}}
$('#theme').onclick=()=>{preference=preference==='system'?'light':preference==='light'?'dark':'system';try{localStorage.setItem('techbuzzs-theme',preference)}catch{}applyTheme()};media.addEventListener('change',()=>{if(preference==='system')applyTheme()});
function projectCard(p){const feature=p.featured?'<span class="feature-label">Featured build</span>':'';return`<article class="project"><button class="preview preview-button" data-open="${p.slug}" aria-label="Preview ${escape(p.name)}"><img loading="lazy" data-preview-slug="${p.slug}" src="previews/${p.slug}-${theme}.png" alt="${escape(p.name)} ${theme} theme screenshot" width="1440" height="1000">${feature}<span class="preview-badge">${p.demo?'Try it here ↗':'Explore project ↗'}</span></button><div class="project-body"><small>${p.category==='landing'?'Original landing page concept':p.category==='utility'?'Working browser utility':p.category==='play'?'Interactive experiment':'Product & systems demo'}</small><h3>${escape(p.name)}</h3><p>${escape(p.description)}</p><div class="tags">${p.tags.map(t=>'<span class="tag">'+escape(t)+'</span>').join('')}</div><div class="project-links"><button data-open="${p.slug}">${p.demo?'Try here':'View details'}</button><a href="${p.url}" target="_blank" rel="noreferrer">Live website ↗</a><a href="${p.repo}" target="_blank" rel="noreferrer">Source code ↗</a></div></div></article>`}
function renderProjects(){const query=$('#projectSearch').value.toLowerCase().trim(),matches=projects.filter(p=>(filter==='all'||p.category===filter)&&(!query||[p.name,p.description,...p.tags].join(' ').toLowerCase().includes(query))),visible=expanded||filter!=='all'||query?matches:matches.slice(0,6);$('#projectGrid').innerHTML=visible.map(projectCard).join('')||'<p class="empty-projects">No matching projects. Try another search or category.</p>';$('#projectCount').textContent=visible.length+' of '+matches.length+' projects'+(query?' matching your search':'');$('#moreProjects').hidden=matches.length<=6||filter!=='all'||!!query;$('#moreProjects').textContent=expanded?'Show fewer projects':'Explore all '+matches.length+' projects ↓';bindOpen($('#projectGrid'))}
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;expanded=false;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderProjects()});$('#projectSearch').oninput=renderProjects;$('#moreProjects').onclick=()=>{expanded=!expanded;renderProjects();if(!expanded)$('#projects').scrollIntoView({behavior:mediaReduce()?'auto':'smooth'})};function mediaReduce(){return matchMedia('(prefers-reduced-motion:reduce)').matches}
function bindOpen(host){host.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openPreview(b.dataset.open))}function sendTheme(){const value=previewPreference==='inherit'?theme:previewPreference;$('#demoFrame').contentWindow?.postMessage({type:'techbuzzs-theme',theme:value},location.origin)}
function openPreview(slug){const p=projects.find(p=>p.slug===slug);if(!p)return;previewProject=p;$('#dialogTitle').textContent=p.name;$('#dialogSubtitle').textContent=p.category==='landing'?'Original concept · booking, signup and cart actions are demonstrations':p.category==='utility'?'Working preview · process files and download results here':p.description;$('#dialogLive').href=p.url;$('#dialogSource').href=p.repo;$('#previewTheme').value='inherit';previewPreference='inherit';$('.frame-shell').classList.remove('mobile');$$('[data-device]').forEach(b=>b.classList.toggle('active',b.dataset.device==='desktop'));$('#previewControls').hidden=!p.demo;$('#detailView').hidden=!!p.demo;$('.frame-shell').hidden=!p.demo;const frame=$('#demoFrame');frame.hidden=!p.demo;if(p.demo){frame.title=p.name+' interactive preview';frame.src='demos/'+p.slug+'/?embed=1&theme='+theme;frame.onload=sendTheme}else{$('#detailView').innerHTML=`<img id="detailImage" src="previews/${p.slug}-${theme}.png" alt="${escape(p.name)} screenshot"><div class="detail-grid"><article><h3>The problem</h3><p>${escape(p.problem)}</p></article><article><h3>The approach</h3><p>${escape(p.approach)}</p></article><article><h3>What to explore</h3><p>${escape(p.try)}</p></article><article><h3>Explore the build</h3><p>${escape(p.tags.join(' · '))}</p><div class="project-links"><a href="${p.url}" target="_blank" rel="noreferrer">Open live project ↗</a><a href="${p.repo}" target="_blank" rel="noreferrer">Read the source ↗</a></div></article></div>`}dialog.showModal()}
$('#closePreview').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{$('#demoFrame').src='about:blank';previewProject=null});dialog.onclick=e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}};$$('[data-device]').forEach(b=>b.onclick=()=>{$$('.preview-controls [data-device]').forEach(x=>x.classList.toggle('active',x===b));$('.frame-shell').classList.toggle('mobile',b.dataset.device==='mobile')});$('#previewTheme').onchange=()=>{previewPreference=$('#previewTheme').value;sendTheme()};
const toolInfo={"image-studio":['<div class="art-crop"></div>','Crop, resize, compress and convert images.'],"document-desk":['<span class="art-mark">PDF → MD</span>','Extract text, merge PDFs and reorder pages.'],"code-canvas":['<div class="art-code">const idea = "hello";<br>makeSomething(idea);</div>','Turn a code snippet into a shareable image.'],"palette-lab":['<div class="art-palette"><i style="background:#d8c7eb"></i><i style="background:#537b72"></i><i style="background:#ecb695"></i><i style="background:#b3cbd0"></i></div>','Find colors, check contrast and export CSS.'],"developer-pocket-tools":['<span class="art-mark">{ } ± ↗</span>','Format JSON, compare text and convert timestamps.'],"qr-studio":['<div class="art-qr">'+Array.from({length:25},()=>'<i></i>').join('')+'</div>','Make QR codes for links, Wi-Fi and contacts.']};$('#toolGrid').innerHTML=projects.filter(p=>p.category==='utility').map(p=>`<article class="tool-card"><div class="tool-art">${toolInfo[p.slug][0]}</div><div class="tool-copy"><h3>${escape(p.name)}</h3><p>${toolInfo[p.slug][1]}</p><div class="tool-actions"><button class="mini-button accent" data-open="${p.slug}">Try sample ↗</button><button class="mini-button" data-open="${p.slug}">Use your ${p.slug==='developer-pocket-tools'?'text':p.slug==='code-canvas'?'code':p.slug==='qr-studio'?'link':'file'}</button><a href="${p.url}" target="_blank" rel="noreferrer">Full tool ↗</a></div></div></article>`).join('');bindOpen($('#toolGrid'));
let skillFilter='all';function renderSkills(){const groups=[...new Set(skills.map(s=>s.group))];$('#skillGrid').innerHTML=groups.filter(g=>skillFilter==='all'||g===skillFilter).map(group=>`<div class="skills-group">${escape(group)}</div>`+skills.filter(s=>s.group===group).map(s=>`<div class="skill">${s.icon?`<img loading="lazy" src="https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/${s.icon}" alt="" width="34" height="34">`:`<div class="icon">${escape(s.label.slice(0,2).toUpperCase())}</div>`}<div><b>${escape(s.label)}</b><span>${escape(s.detail)}</span></div></div>`).join('')).join('')}
$$('[data-skill]').forEach(b=>b.onclick=()=>{skillFilter=b.dataset.skill;$$('[data-skill]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderSkills()});
let paletteIndex=0;const palettes=[['#e9d8bc','#344e48','#c67c5a','#9daf9a','#b6a6c8'],['#e4e8f8','#33476b','#857bcd','#6bb4ad','#e8b27e'],['#f7e6d9','#795260','#c28b75','#e1bb85','#99b7af']];function palette(){$('#inlineSwatches').replaceChildren();palettes[paletteIndex].forEach(color=>{const button=document.createElement('button');button.style.background=color;button.setAttribute('aria-label','Copy color '+color);button.innerHTML='<span>'+color.toUpperCase()+'</span>';button.onclick=async()=>{try{await navigator.clipboard.writeText(color);$('#paletteStatus').textContent='Copied '+color.toUpperCase()}catch{$('#paletteStatus').textContent=color.toUpperCase()+' — select and copy this color.'}};$('#inlineSwatches').append(button)})}$('#shuffleInline').onclick=()=>{paletteIndex=(paletteIndex+1)%palettes.length;palette();$('#paletteStatus').textContent='A new palette. Click a color to copy it.'};$('#fullPalette').onclick=()=>openPreview('palette-lab');applyTheme();renderProjects();renderSkills();palette();initGames();
